function palette(h){if(typeof h!=="string"||!/^#[\da-f]{6}$/i.test(h))return h;const a=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));if(Math.max(...a)<=85||Math.min(...a)>=235)return h;const inv=a.map(n=>255-n);let best=colors[0],d=Infinity;for(const c of colors){const q=[1,3,5].map(i=>parseInt(c.slice(i,i+2),16));const t=q.reduce((sum,v,i)=>sum+(v-inv[i])**2,0);if(t<d){d=t;best=c}}return best}
function points(n){return Array.from({length:n},(_,i)=>{const a=-Math.PI/2+i*2*Math.PI/n;return{x:50+41*Math.cos(a),y:50+39*Math.sin(a)}})}
function validate(d){if(!d?.id||!d.title||!Array.isArray(d.modules)||!d.modules.length)throw Error("Dati visuali non validi");const ids=new Set();for(const m of d.modules){if(!m.id||!m.title||!m.blocks?.length||ids.has(m.id))throw Error("Ramo non valido");ids.add(m.id);for(const b of m.blocks){if(!b.id||!b.title||ids.has(b.id))throw Error("Nodo non valido");ids.add(b.id)}}return true}
