function nextIndex(d,b,i,delta){const m=d.modules.find(x=>x.id===b)||d.modules[0];return Math.max(0,Math.min(m.blocks.length-1,i+delta))}

function cleanTitle(t){return String(t||"").trim().replace(/\s+/g," ").slice(0,100)}
function addChild(rows,parent,title,audio,id){title=cleanTitle(title);if(!title)throw Error("Inserisci il nome del ramo.");if(rows.some(r=>r.id===id))throw Error("Identificativo duplicato.");if(rows.some(r=>r.parent===parent&&r.title.toLocaleLowerCase()===title.toLocaleLowerCase()))throw Error("Ramo già esistente.");return [...rows,{id,parent,title,label:title,audio:String(audio||"").trim().slice(0,12000)}]}
function safeImage(v){return typeof v==="string"&&(/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(v)||/^https:\/\/[^\s]+$/i.test(v))}
function parentTrail(id,find){const result=[],seen=new Set();let n=find(id);while(n&&!seen.has(n.id)){seen.add(n.id);result.unshift(n);n=n.parent?find(n.parent):null}return result}

function preferredItalian(voices){const it=Array.from(voices||[]).filter(v=>/^it(?:[-_]|$)/i.test(v.lang||""));const score=v=>{const n=v.name||"";return (/google/i.test(n)?1000:0)+(/natural|neural|premium|enhanced|wavenet/i.test(n)?100:0)+(/^it[-_]it$/i.test(v.lang)?20:0)+(v.localService?5:0)};return it.sort((a,b)=>score(b)-score(a))[0]||null}
function audioTimeline(parts,rate=1){const speeds=Math.max(.4,Math.min(2,Number(rate)||1));let total=0;const starts=Array.from(parts||[],t=>{const p=total;total+=Math.max(1,String(t).trim().split(/\s+/).filter(Boolean).length*60/150+.35)/speeds;return p});return {starts,total}}
function audioJump(parts,index,delta,rate=1){const {starts}=audioTimeline(parts,rate);if(!starts.length)return 0;index=Math.max(0,Math.min(starts.length-1,Math.floor(index)||0));const goal=Math.max(0,starts[index]+delta);let next=0;for(let i=0;i<starts.length;i++){if(starts[i]<=goal)next=i;else break}if(delta>0&&next===index)next=Math.min(index+1,starts.length-1);if(delta<0&&next===index)next=Math.max(0,index-1);return next}
function removePersonalBranch(edits,id,protectedIds=new Set()){if(protectedIds.has(id)||!edits.children.some(n=>n.id===id))throw Error("Ramo originale protetto.");const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const n of edits.children){if(ids.has(n.parent)&&!ids.has(n.id)){if(protectedIds.has(n.id))throw Error("Ramo originale protetto.");ids.add(n.id);changed=true}}}return {next:{...edits,children:edits.children.filter(n=>!ids.has(n.id)),images:Object.fromEntries(Object.entries(edits.images).filter(([k])=>!ids.has(k))),layers:Object.fromEntries(Object.entries(edits.layers||{}).filter(([k])=>!ids.has(k))),hidden:Object.fromEntries(Object.entries(edits.hidden||{}).filter(([k])=>!ids.has(k)))},ids}}
function cleanLayers(raw){if(!raw||typeof raw!=="object"||Array.isArray(raw))return {};return Object.fromEntries(Object.entries(raw).filter(([id,a])=>typeof id==="string"&&Array.isArray(a)).map(([id,a])=>[id,a.filter(l=>l&&typeof l.id==="string"&&(l.src==="builtin:feet"||safeImage(l.src))).slice(0,12).map(l=>({id:l.id,src:l.src,x:Math.max(0,Math.min(100,Number.isFinite(l.x)?l.x:50)),y:Math.max(0,Math.min(100,Number.isFinite(l.y)?l.y:25)),size:Math.max(10,Math.min(100,Number.isFinite(l.size)?l.size:45)),rotation:Math.max(-180,Math.min(180,Number.isFinite(l.rotation)?l.rotation:0))}))]))}
